{"command":"POD=$(kubectl -n default get pod -l app=app -o jsonpath='{.items[0].metadata.name}'); echo "pod=$POD"; kubectl -n default exec "$POD" -- curl -sS -m 5 -o /dev/null -w 'curl_code=%{http_code}\n' http://127.0.0.1/ || (kubectl -n default exec "$POD" -- python3 - <<PY
import socket
s=socket.socket(); s.connect(("127.0.0.1",80)); b=s.recv(4096); print(len(b),b[:30]); s.close()
PY
)"}

